script:
/* twofold_styles: Dusk slate, one theme (dark). Calm motion: feedback at 120 to 180ms, the switch's own change at 280ms, all ease-out; nothing moves on scroll. */
:root { color-scheme: dark; }
@view-transition { navigation: auto; }
html, body { overflow-x: clip; }
html { background-color: var(--90ceef84-5634-4c58-948d-ab8b7a53fd8a); color: var(--4eb6c52a-bd37-4578-a239-77714376d382); scrollbar-color: var(--543912ec-00bd-40f1-a5ea-edcaab7caea5) var(--90ceef84-5634-4c58-948d-ab8b7a53fd8a); scroll-padding-top: 96px; }
body { caret-color: var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); -webkit-font-smoothing: antialiased; }
::selection { background-color: color-mix(in oklab, var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee) 22%, transparent); color: var(--4eb6c52a-bd37-4578-a239-77714376d382); }
input, textarea, select { accent-color: var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); }
:focus-visible { outline: 2px solid var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); outline-offset: 2px; }
h1, h2, h3 { text-wrap: balance; overflow-wrap: break-word; min-width: 0; font-synthesis: none; }
p { text-wrap: pretty; }
/* Builder renders a paragraph block as a div: give those the same wrapping (zero specificity, so a block's own setting wins) */
:where(div.__text_block__) { text-wrap: pretty; }
.twofold-num, a[href^="tel:"] { font-variant-numeric: tabular-nums; }
.twofold-wordmark { view-transition-name: twofold-brand; transition: opacity 180ms cubic-bezier(0.16, 1, 0.3, 1); }
.twofold-wordmark:hover { opacity: 0.8; }
.twofold-wordmark:focus-visible { outline-offset: 4px; border-radius: 2px; }

.twofold-skip:focus-visible { top: 16px; }
/* the skip link's target takes focus so screen readers announce the jump; the region itself shows no ring */
#main:focus { outline: none; }

/* controls: one filled recipe, a ghost, two link styles */
.twofold-btn, .twofold-ghost { transition: background-color 180ms cubic-bezier(0.16, 1, 0.3, 1), color 180ms cubic-bezier(0.16, 1, 0.3, 1), box-shadow 180ms cubic-bezier(0.16, 1, 0.3, 1), transform 120ms cubic-bezier(0.16, 1, 0.3, 1); }
.twofold-btn:hover { background-color: var(--0debe306-affa-4880-a2ce-a47b186936a0); box-shadow: inset 0 1px 0 color-mix(in oklab, var(--8e8474f8-bc90-4465-ac11-1631416a8d56) 35%, transparent), 0 0 0 4px color-mix(in oklab, var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee) 22%, transparent); }
.twofold-btn-deep:hover { background-color: color-mix(in oklab, var(--153d0a30-ff92-44df-b9cf-dca9e72d34cb) 84%, var(--660fb09f-d93a-4591-aef0-2caf8b135791)); box-shadow: 0 0 0 4px color-mix(in oklab, var(--153d0a30-ff92-44df-b9cf-dca9e72d34cb) 22%, transparent); }
.twofold-btn:active, .twofold-ghost:active { transform: translateY(1px) scale(0.98); }
.twofold-btn:focus-visible, .twofold-ghost:focus-visible { outline: 2px solid var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); outline-offset: 3px; transition: none; }
.twofold-btn-deep:focus-visible { outline-color: var(--153d0a30-ff92-44df-b9cf-dca9e72d34cb); }
.twofold-btn[aria-busy="true"] { cursor: progress; }
.twofold-btn:disabled, .twofold-btn[aria-disabled="true"], .twofold-ghost[aria-disabled="true"] { opacity: 0.55; cursor: not-allowed; transform: none; }
a[href^="tel:"], .twofold-credits a { white-space: nowrap; }
.twofold-ghost:hover, .twofold-ghost[aria-current="page"] { background-color: color-mix(in oklab, var(--8e8474f8-bc90-4465-ac11-1631416a8d56) 11%, transparent); }
a.twofold-link { position: relative; text-decoration: none; }
a.twofold-link::after { content: ""; position: absolute; left: 0; right: 0; bottom: -0.16em; height: 1px; background-color: currentColor; opacity: 0; transition: opacity 180ms cubic-bezier(0.16, 1, 0.3, 1); }
a.twofold-link:hover::after, a.twofold-link[aria-current="page"]::after { opacity: 1; }
a.twofold-link:focus-visible, a.twofold-rest:focus-visible { outline: 2px solid var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); outline-offset: 3px; border-radius: 2px; }
a.twofold-link:active, a.twofold-rest:active { opacity: 0.72; }
a.twofold-rest { text-decoration-line: underline; text-decoration-style: solid; text-decoration-thickness: 1px; text-underline-offset: 0.26em; text-decoration-color: color-mix(in oklab, currentColor 40%, transparent); transition: text-decoration-color 180ms cubic-bezier(0.16, 1, 0.3, 1), opacity 120ms cubic-bezier(0.16, 1, 0.3, 1); }
a.twofold-rest:hover, a.twofold-rest[aria-current="page"] { text-decoration-color: currentColor; }
a.twofold-line { position: relative; color: inherit; text-decoration: none; white-space: nowrap; font-variant-numeric: lining-nums; }
a.twofold-line::after { content: ""; position: absolute; left: 0; right: 0; bottom: -0.16em; height: 0.06em; min-height: 2px; background-color: currentColor; opacity: 0.35; transition: opacity 180ms cubic-bezier(0.16, 1, 0.3, 1); }
a.twofold-line:hover::after { opacity: 1; }
a.twofold-line:focus-visible { outline: 2px solid var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); outline-offset: 4px; border-radius: 2px; }
.twofold-call-or a { color: var(--4eb6c52a-bd37-4578-a239-77714376d382); }

/* nav: clear over the photograph band, slate glass past it; links give way to the mini switch */
.twofold-nav-glass { transition: opacity 180ms cubic-bezier(0.16, 1, 0.3, 1); }
.twofold-nav.is-solid .twofold-nav-glass { opacity: 1; }
.twofold-nav-links { transition: opacity 180ms cubic-bezier(0.16, 1, 0.3, 1), visibility 0s linear 0s; }
.twofold-nav.is-swapped .twofold-nav-links { opacity: 0; visibility: hidden; transition-delay: 0s, 180ms; }
.twofold-nav-switch { transition: opacity 180ms cubic-bezier(0.16, 1, 0.3, 1), visibility 0s linear 180ms; }
.twofold-nav.is-swapped .twofold-nav-switch { opacity: 1; visibility: visible; transition-delay: 0s; }

/* who the page is for: one audience shows once a script has set it; the editor shows both, tagged */
html.twofold-js:not([data-audience="business"]) [data-aud="business"],
html.twofold-js[data-audience="business"] [data-aud="personal"] { display: none; }
html.twofold-js .twofold-tag { display: none; }

/* a component's own styles arrive after its markup: hold every transition until the page has
   arrived, so a late style never animates the first paint (a script adds twofold-settled) */
html.twofold-js:not(.twofold-settled) *, html.twofold-js:not(.twofold-settled) *::before, html.twofold-js:not(.twofold-settled) *::after { transition: none !important; }

/* the signature's own change: the photographs crossfade by opacity, 280ms, nothing scales or drifts */
.twofold-photo { transition: opacity 280ms cubic-bezier(0.16, 1, 0.3, 1); }
html[data-audience="business"] .twofold-photo.is-personal { opacity: 0; }
html[data-audience="business"] .twofold-photo.is-business { opacity: 1; }

/* between 1024 and 1088px the hero plate and the year chart need the room the comp gives them at 68rem */
@media (min-width: 1024px) and (max-width: 1088px) {
	.twofold-hero-lede, .twofold-hero-actions { grid-column: 1 / span 7; }
	.twofold-hero-plate { grid-column: 1 / span 7; grid-row: 4; align-self: start; margin-top: 40px; }
	.twofold-year-chart { grid-column: 1 / span 7; padding: 40px; }
	/* services: the banner plate drops under the head; consultation: the slip takes a column more */
	.twofold-banner-text { grid-column: 1 / -1; }
	.twofold-banner-plate { grid-column: 1 / span 8; margin-top: 40px; }
	.twofold-book-slip { grid-column: 6 / -1; }
}

/* reduced motion: every state changes at once, no page crossfade */
@media (prefers-reduced-motion: reduce) {
	*, *::before, *::after { transition: none !important; }
	::view-transition-group(*), ::view-transition-old(*), ::view-transition-new(*) { animation: none !important; }
}
